# -*- coding: utf-8 -*-
"""Generates 92 additional JEV example scripts (bringing the total to 100
across 20 sectors), each in its own sector folder, following the same
pattern as the 8 hand-written originals: one noul gate, one choice route,
one score priority, run against JEVzilla(backend="openrouter")."""
import os

BASE = os.path.join(os.path.dirname(__file__), "examples")

TEMPLATE = '''"""
{sector_title} — {title}.

Scenario: {scenario}

Run:
    set OPENROUTER_API_KEY=your-key
    python {fname}.py
"""
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from _display import print_verdict
from jevzilla import JEVzilla

STATE = {state!r}

QUESTIONS = {{
    "{gate_key}": {{
        "type": "noul",
        "instructions": {gate_instr!r},
        "criteria": {{"true": {gate_true!r}, "false": {gate_false!r}}},
    }},
    "{route_key}": {{
        "type": "choice",
        "instructions": {route_instr!r},
        "criteria": {route_opts!r},
    }},
    "{score_key}": {{
        "type": "score",
        "instructions": {score_instr!r},
        "criteria": {score_levels!r},
    }},
}}

if __name__ == "__main__":
    jev = JEVzilla(backend="openrouter")
    res = jev.evaluate({{"state": STATE, "questions": QUESTIONS}})
    print_verdict("{sector_title} — {title}", {summary!r}, res.answers)
'''

# Each entry: (sector_folder, sector_title, filename, title, scenario_text, state_dict,
#              summary, gate_key, gate_instr, gate_true, gate_false,
#              route_key, route_instr, route_opts, score_key, score_instr, score_levels)
