count = 0
for (folder, sector_title, fname, title, scenario, state, summary,
     gate_key, gate_instr, gate_true, gate_false,
     route_key, route_instr, route_opts,
     score_key, score_instr, score_levels) in SCENARIOS:
    outdir = os.path.join(BASE, folder)
    os.makedirs(outdir, exist_ok=True)
    content = TEMPLATE.format(
        sector_title=sector_title, title=title, scenario=scenario, fname=fname,
        state=state, gate_key=gate_key, gate_instr=gate_instr, gate_true=gate_true,
        gate_false=gate_false, route_key=route_key, route_instr=route_instr,
        route_opts=route_opts, score_key=score_key, score_instr=score_instr,
        score_levels=score_levels, summary=summary,
    )
    path = os.path.join(outdir, fname + ".py")
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    count += 1

print(f"Generated {count} new example files.")
